    const source = decodeGlobalNodeIdAny(reader);
    const scope = decodeLocalScopeId(reader);
    const symbol_ = reader.readOption(() => decodeGlobalSymbolId(reader));
    const parameters = (() => {
        const length3 = reader.readNumber();
        const items3: Array<LocalGenericParameterId> = [];
        for (let index = 0; index < length3; index += 1) {
            items3.push(decodeLocalGenericParameterId(reader));
        }
        return items3;
    })();
    const predicates = (() => {
        const length4 = reader.readNumber();
        const items4: Array<WherePredicate> = [];
        for (let index = 0; index < length4; index += 1) {
            items4.push(decodeWherePredicate(reader));
        }
        return items4;
    })();

    return {
        source,
        scope,
        ...(symbol_ === undefined ? {} : { symbol: symbol_ }),
        parameters,
        predicates,
    };
